def text_plot(f, xmin, xmax, ymin, ymax):
    # Prints the graph of f: a column for each whole number x, a row for each whole number y
    for y in range(ymax, ymin - 1, -1):
        row = ""
        for x in range(xmin, xmax + 1):
            if y - 0.5 <= f(x) < y + 0.5:
                mark = "*"
            elif x == 0 and y == 0:
                mark = "+"
            elif x == 0:
                mark = "|"
            elif y == 0:
                mark = "-"
            else:
                mark = "."
            row = row + mark + " "
        print(row)


def f(x):
    return x ** 2

cases = [
    ("up 3", 0, 3),
    ("down 4", 0, -4),
    ("right 3", 3, 0),
    ("left 2", -2, 0),
    ("right 3 and up 2", 3, 2),
]
for label, h, k in cases:
    print(f"{label}: y = f(x - ({h})) + ({k}), lowest point (0, 0) -> ({h}, {k}), (1, 1) -> ({1 + h}, {1 + k})")
print("y = (x - 3)^2 + 2:")
text_plot(lambda x: f(x - 3) + 2, -2, 6, -1, 7)

