from fractions import Fraction

def f(x):
    return x * (4 - x)

count = int(input())
for i in range(count):
    a = int(input())
    b = int(input())
    images = []
    for p in [0, 2, 4]:
        images.append(f"({Fraction(p, b)}, {a * f(p)})")
    print(f"a = {a}, b = {b}: " + ", ".join(images))

count = int(input())
for i in range(count):
    n = int(input())
    c = []
    for k in range(n + 1):
        c.append(int(input()))
    even = all(c[k] == 0 for k in range(1, n + 1, 2))
    odd = all(c[k] == 0 for k in range(0, n + 1, 2))
    if even and odd:
        kind = "both"
    elif even:
        kind = "even"
    elif odd:
        kind = "odd"
    else:
        kind = "neither"
    print(f"{c}: {kind}")
